type Restaurant = {
  id: string;
  name: string;
  slug: string;
  theme_key: string | null;
  phone: string | null;
  address_line_1: string | null;
  city: string | null;
  state: string | null;
  zip: string | null;
};

type WebsiteSettings = {
  published: boolean | null;
};

type PageRow = {
  id: string;
  restaurant_id: string;
  page_type: string;
  title: string;
  slug: string;
  nav_label: string | null;
  content: string | null;
  hero_image_url: string | null;
  active: boolean;
  show_in_nav: boolean;
  sort_order: number | null;
};

export default function PublicCustomPage() {
  const params = useParams();
  const siteSlug = String(params?.slug || "");
  const pageSlug = String(params?.page || "");

  const [restaurant, setRestaurant] = useState<Restaurant | null>(null);
  const [website, setWebsite] = useState<WebsiteSettings | null>(null);
  const [page, setPage] = useState<PageRow | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!siteSlug || !pageSlug) return;
    loadPage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [siteSlug, pageSlug]);

  async function loadPage() {
    setLoading(true);

    const { data: restaurantData } = await publicSupabase
      .from("restaurants")
      .select("id,name,slug,theme_key,phone,address_line_1,city,state,zip")
      .eq("slug", siteSlug)
      .maybeSingle();

    if (!restaurantData) {
      setRestaurant(null);
      setLoading(false);
      return;
    }

    const [websiteResult, pageResult] = await Promise.all([
      publicSupabase
        .from("restaurant_website_settings")
        .select("published")
        .eq("restaurant_id", restaurantData.id)
        .maybeSingle(),

      publicSupabase
        .from("restaurant_pages")
        .select("*")
        .eq("restaurant_id", restaurantData.id)
        .eq("slug", pageSlug)
        .eq("active", true)
        .maybeSingle(),
    ]);

    setRestaurant(restaurantData as Restaurant);
    setWebsite((websiteResult.data || null) as WebsiteSettings | null);
    setPage((pageResult.data || null) as PageRow | null);
    setLoading(false);
  }

  if (loading) {
    return <div style={{ minHeight: "100vh", background: "#061a31" }} />;
  }

  if (!restaurant || !website?.published || !page) {
    return (
      <main style={{
        minHeight: "100vh",
        display: "grid",
        placeItems: "center",
        background: "#061a31",
        color: "white",
        fontFamily: "Arial, sans-serif",
      }}>
        <div>Page not available.</div>
      </main>
    );
  }

  if (restaurant.theme_key !== "vi-pollos-custom") {
    return <GenericPage restaurant={restaurant} page={page} />;
  }

  return <ViPollosPage restaurant={restaurant} page={page} />;
}

