function ContactPageContent() {
  const [name,setName] = useState("");
  const [email,setEmail] = useState("");
  const [phone,setPhone] = useState("");
  const [message,setMessage] = useState("");

  function send(event:FormEvent) {
    event.preventDefault();
    const subject = encodeURIComponent(`Vi Pollos Website Inquiry from ${name || "Customer"}`);
    const body = encodeURIComponent(
      `Name: ${name}\nEmail: ${email}\nPhone: ${phone}\n\nMessage:\n${message}`
    );
    window.location.href = `mailto:${VI_EMAIL}?subject=${subject}&body=${body}`;
  }

  return (
    <section className="section">
      <div className="contactWrap">
        <aside className="contactInfo">
          <div className="eyebrow">GET IN TOUCH</div>
          <h2>We’d Love to Hear From You.</h2>
          <p>
            Questions about catering, large orders, events or Vi Pollos? Send us a message or call the restaurant directly.
          </p>
          <p>
            <strong>Vi Pollos</strong><br/>
            {VI_ADDRESS}<br/>
            (919) 879-8000<br/>
            {VI_EMAIL}
          </p>
          <div className="buttonRow">
            <a className="goldBtn" href={`tel:${VI_PHONE}`}>CALL NOW</a>
            <a className="outlineBtn" href={ORDER_URL} target="_blank" rel="noreferrer">ORDER ONLINE</a>
          </div>
        </aside>

        <form className="contactForm" onSubmit={send}>
          <div className="eyebrow">SEND A MESSAGE</div>
          <h2 style={{ margin:"10px 0 26px", color:"#0b355f", fontFamily:"Georgia,serif", fontSize:"40px" }}>Contact Vi Pollos</h2>
          <div className="formGrid">
            <div className="field"><label>NAME</label><input value={name} onChange={e=>setName(e.target.value)} required /></div>
            <div className="field"><label>EMAIL</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required /></div>
            <div className="field full"><label>PHONE</label><input value={phone} onChange={e=>setPhone(e.target.value)} /></div>
            <div className="field full"><label>MESSAGE</label><textarea value={message} onChange={e=>setMessage(e.target.value)} required /></div>
          </div>
          <button className="sendBtn" type="submit">SEND TO VI POLLOS</button>
        </form>
      </div>
    </section>
  );
}

function GenericPage({ restaurant, page }: { restaurant:Restaurant; page:PageRow }) {
  return (
    <main style={{ minHeight:"100vh", background:"#07111c", color:"white", padding:"60px", fontFamily:"Arial,sans-serif" }}>
      <a href={`/r/${restaurant.slug}`}>← BACK HOME</a>
      <h1 style={{ fontSize:"64px" }}>{page.title}</h1>
      <p style={{ maxWidth:"800px", lineHeight:1.8, whiteSpace:"pre-line" }}>{page.content}</p>
    </main>
  );
}
